"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[47786],{41758:e=>{e.exports=JSON.parse('{"tag":{"label":"getting started","permalink":"/docs/tags/getting-started","allTagsPath":"/docs/tags","count":54,"items":[{"id":"Degus/getting-started/degu-basic-care","title":"Basic Care","description":"Degu Basic Care","permalink":"/docs/Degus/getting-started/degu-basic-care"},{"id":"Ferrets/getting-started/ferret-basic-care","title":"Basic Care","description":"Ferret Basic Care","permalink":"/docs/Ferrets/getting-started/ferret-basic-care"},{"id":"Gerbils/getting-started/gerbil-basic-care","title":"Basic Care","description":"Gerbil Basic Care","permalink":"/docs/Gerbils/getting-started/gerbil-basic-care"},{"id":"Hamsters/getting-started/hamster-basic-care","title":"Basic Care","description":"Hamsters are popular pets, known for their chubby cheeks and love of running on their wheel. While they are small, they still require consistent care to thrive. This guide covers the daily, weekly, and monthly tasks needed to keep your hamster healthy and happy.","permalink":"/docs/Hamsters/getting-started/hamster-basic-care"},{"id":"Hedgehogs/getting-started/hedgehog-basic-care","title":"Basic Care","description":"Hedgehog Basic Care","permalink":"/docs/Hedgehogs/getting-started/hedgehog-basic-care"},{"id":"Mice/getting-started/mouse-basic-care","title":"Basic Care","description":"Mice are intelligent, social, and active little animals that can make engaging pets. Proper care is essential to ensure they live a full and stimulating life. This guide outlines the key aspects of caring for pet mice.","permalink":"/docs/Mice/getting-started/mouse-basic-care"},{"id":"Chinchillas/getting-started/chinchilla-habitat","title":"chinchilla-habitat","description":"Chinchilla Habitat","permalink":"/docs/Chinchillas/getting-started/chinchilla-habitat"},{"id":"Rats/getting-started/essential-rat-supplies","title":"Essential Rat Supplies","description":"Bringing pet rats home requires some preparation. Rats are intelligent, social animals with specific needs, and having the right supplies in place before they arrive will make the transition much smoother for both you and your new companions. This guide covers everything you need to set up a safe, comfortable, and enriching home for your rats.","permalink":"/docs/Rats/getting-started/essential-rat-supplies"},{"id":"Chinchillas/getting-started/essential-supplies","title":"Essential Supplies for Pet Chinchillas","description":"A complete checklist of the essential supplies required to create a safe, healthy, and enriching environment for pet chinchillas.","permalink":"/docs/Chinchillas/getting-started/essential-supplies"},{"id":"Degus/getting-started/essential-supplies","title":"Essential Supplies for Pet Degus","description":"A comprehensive checklist of all the essential supplies needed to provide a safe, enriching, and healthy environment for your pet degus.","permalink":"/docs/Degus/getting-started/essential-supplies"},{"id":"Ferrets/getting-started/essential-supplies","title":"Essential Supplies for Pet Ferrets","description":"A complete checklist of the essential supplies needed to create a safe, stimulating, and comfortable home for pet ferrets.","permalink":"/docs/Ferrets/getting-started/essential-supplies"},{"id":"Gerbils/getting-started/essential-supplies","title":"Essential Supplies for Pet Gerbils","description":"A comprehensive checklist of the essential supplies needed to set up a safe, enriching, and appropriate habitat for pet gerbils.","permalink":"/docs/Gerbils/getting-started/essential-supplies"},{"id":"Hamsters/getting-started/essential-supplies","title":"Essential Supplies for Pet Hamsters","description":"A complete checklist of essential supplies needed to create a safe, comfortable, and stimulating environment for a pet hamster.","permalink":"/docs/Hamsters/getting-started/essential-supplies"},{"id":"Hedgehogs/getting-started/essential-supplies","title":"Essential Supplies for Pet Hedgehogs","description":"A complete checklist of the essential supplies needed to set up a safe, warm, and stimulating environment for a pet hedgehog.","permalink":"/docs/Hedgehogs/getting-started/essential-supplies"},{"id":"Mice/getting-started/essential-supplies","title":"Essential Supplies for Pet Mice","description":"A comprehensive checklist of all the essential supplies you need to provide a safe, enriching, and healthy environment for your pet mice.","permalink":"/docs/Mice/getting-started/essential-supplies"},{"id":"guinea-pigs/getting-started/essential-supplies","title":"essential-supplies","description":"Bringing home a guinea pig (or better yet\u2014a pair!) is an exciting and joyful experience. To set your new friends up for a happy, healthy life, it\u2019s important to have the right supplies ready from day...","permalink":"/docs/guinea-pigs/getting-started/essential-supplies"},{"id":"guinea-pigs/getting-started/guineapigcare","title":"guineapigcare","description":"Plain, quality pellets are best for guinea pigs. Guinea pigs under 6 months old should be fed an Alfalfa pellet and hay-based diet. Do not feed your guinea pig any food with artificial coloring,...","permalink":"/docs/guinea-pigs/getting-started/guineapigcare"},{"id":"Degus/getting-started/degu-habitat","title":"Habitat","description":"Degus are active, agile, and curious animals that need a large and stimulating environment to thrive. Their habitat must be chew-proof and designed to accommodate their love of climbing, running, and...","permalink":"/docs/Degus/getting-started/degu-habitat"},{"id":"Ferrets/getting-started/ferret-habitat","title":"Habitat","description":"Ferrets are intelligent, playful, and incredibly curious. Their habitat needs to be a safe and secure home base, but it is not where they should spend all their time. A ferret\'s cage is for sleeping,...","permalink":"/docs/Ferrets/getting-started/ferret-habitat"},{"id":"Gerbils/getting-started/gerbil-habitat","title":"Habitat","description":"Creating the right environment is one of the most important things you can do for your gerbils. As natural burrowers, their habitat needs to accommodate their instinct to dig. A proper setup will...","permalink":"/docs/Gerbils/getting-started/gerbil-habitat"},{"id":"Hamsters/getting-started/hamster-habitat","title":"Habitat","description":"A hamster\'s cage is its entire world, so creating a safe, spacious, and enriching environment is the most important responsibility of any owner. The right habitat prevents stress, boredom, and escape...","permalink":"/docs/Hamsters/getting-started/hamster-habitat"},{"id":"Hedgehogs/getting-started/hedgehog-habitat","title":"Habitat","description":"Creating a safe, warm, and stimulating habitat is the most important part of hedgehog ownership. Their enclosure is their entire world, and it must be set up to meet their unique needs, especially...","permalink":"/docs/Hedgehogs/getting-started/hedgehog-habitat"},{"id":"Mice/getting-started/mouse-habitat","title":"Habitat","description":"Mice are active, curious, and love to climb and explore. Their habitat should be designed to accommodate these natural behaviors, providing plenty of space and enrichment to keep them happy and...","permalink":"/docs/Mice/getting-started/mouse-habitat"},{"id":"general-care/daily-care/hand-feeding","title":"hand-feeding","description":"A step-by-step guide on how to safely and effectively hand-feed a sick, orphaned, or convalescing small pet using a syringe. Learn about preparing the food, proper feeding technique, and what to watch for.","permalink":"/docs/general-care/daily-care/hand-feeding"},{"id":"general-care/getting-a-pet/foundpet","title":"Help, I Found a Pet!","description":"* Is it a pet?","permalink":"/docs/general-care/getting-a-pet/foundpet"},{"id":"guinea-pigs/health-and-wellness/home-health-care","title":"home-health-care","description":"Guinea pigs are hardy little creatures, but they rely on attentive caregivers to keep them healthy and comfortable. Performing regular home health checks is one of the most important things you can...","permalink":"/docs/guinea-pigs/health-and-wellness/home-health-care"},{"id":"general-care/daily-care/introductions-and-quarantine","title":"introductions-and-quarantine","description":"Learn the critical importance of quarantining new pets to prevent the spread of illness and the proper, gradual steps for introducing them to your resident animals to ensure a peaceful household.","permalink":"/docs/general-care/daily-care/introductions-and-quarantine"},{"id":"Gerbils/getting-started/is-a-gerbil-right-for-me","title":"Is a Gerbil Right for You?","description":"Gerbils are curious, active, and social animals that can make wonderful pets for the right family. However, like any animal, they have specific needs that must be met to ensure they live a happy and...","permalink":"/docs/Gerbils/getting-started/is-a-gerbil-right-for-me"},{"id":"Chinchillas/getting-started/is-a-chinchilla-right-for-me","title":"is-a-chinchilla-right-for-me","description":"Chinchillas are extraordinary animals \u2014 soft as velvet, agile as acrobats, and capable of living 20 years or more with excellent care. That extraordinary lifespan is also the most important thing to...","permalink":"/docs/Chinchillas/getting-started/is-a-chinchilla-right-for-me"},{"id":"Degus/getting-started/is-a-degu-right-for-me","title":"is-a-degu-right-for-me","description":"Degus are social, intelligent, and endlessly entertaining little animals \u2014 but they are also one of the more demanding small pets in terms of housing, diet, and specialized knowledge. They are not...","permalink":"/docs/Degus/getting-started/is-a-degu-right-for-me"},{"id":"Ferrets/getting-started/is-a-ferret-right-for-me","title":"is-a-ferret-right-for-me","description":"Ferrets are playful, mischievous, and deeply entertaining companions \u2014 often described as \'cats in a slinky body.\' They are also one of the more demanding small pets, with significant time...","permalink":"/docs/Ferrets/getting-started/is-a-ferret-right-for-me"},{"id":"guinea-pigs/getting-started/is-a-guinea-pig-right-for-me","title":"is-a-guinea-pig-right-for-me","description":"Guinea pigs are gentle, social, and surprisingly communicative little animals \u2014 and they are one of the most rewarding small pets you can share your home with. But like any pet, they come with real...","permalink":"/docs/guinea-pigs/getting-started/is-a-guinea-pig-right-for-me"},{"id":"Hamsters/getting-started/is-a-hamster-right-for-me","title":"is-a-hamster-right-for-me","description":"Hamsters are often purchased as a first pet for young children, but the reality of hamster ownership frequently surprises families who aren\'t prepared. They are fascinating, complex animals \u2014 but...","permalink":"/docs/Hamsters/getting-started/is-a-hamster-right-for-me"},{"id":"Hedgehogs/getting-started/is-a-hedgehog-right-for-me","title":"is-a-hedgehog-right-for-me","description":"Hedgehogs are unique, fascinating animals with big personalities packed into a small, spiny package. They are not cuddly in the traditional sense \u2014 most hedgehogs take time to warm up to handling,...","permalink":"/docs/Hedgehogs/getting-started/is-a-hedgehog-right-for-me"},{"id":"Mice/getting-started/is-a-mouse-right-for-me","title":"is-a-mouse-right-for-me","description":"Mice are often overlooked as pets, but they are endlessly entertaining, relatively affordable, and surprisingly personable. They are best suited to older children, teenagers, and adults who enjoy...","permalink":"/docs/Mice/getting-started/is-a-mouse-right-for-me"},{"id":"Rabbits/getting-started/is-a-rabbit-right-for-me","title":"is-a-rabbit-right-for-me","description":"Rabbits are among the most popular pets in the United States \u2014 and among the most frequently surrendered. The gap between expectation and reality is wide: many families bring home a rabbit imagining...","permalink":"/docs/Rabbits/getting-started/is-a-rabbit-right-for-me"},{"id":"Rats/getting-started/is-a-rat-right-for-me","title":"is-a-rat-right-for-me","description":"Rats are among the most intelligent, affectionate, and interactive small pets you can keep. They learn their names, come when called, enjoy being held and carried, and form genuine bonds with their...","permalink":"/docs/Rats/getting-started/is-a-rat-right-for-me"},{"id":"general-care/daily-care/is-my-pet-nocturnal","title":"is-my-pet-nocturnal","description":"Learn the difference between nocturnal, diurnal, and crepuscular activity patterns and find out when your small pet is naturally most active. Understanding their sleep cycle is key to providing the best care.","permalink":"/docs/general-care/daily-care/is-my-pet-nocturnal"},{"id":"Rabbits/breeds-and-genetics/know-your-rabbit-breeds","title":"Know Your Rabbit Breeds","description":"A guide to popular pet rabbit breeds recognized by the American Rabbit Breeders Association, including size, temperament, and care considerations.","permalink":"/docs/Rabbits/breeds-and-genetics/know-your-rabbit-breeds"},{"id":"general-care/health-and-medical/mastitis","title":"mastitis","description":"An overview of mastitis, a painful infection of the mammary glands, in small pets. Learn to recognize the signs, understand the causes, and know when to seek immediate veterinary care.","permalink":"/docs/general-care/health-and-medical/mastitis"},{"id":"Chinchillas/getting-started/nutrition","title":"nutrition","description":"Chinchilla Nutrition","permalink":"/docs/Chinchillas/getting-started/nutrition"},{"id":"Degus/getting-started/degu-nutrition","title":"Nutrition","description":"Proper nutrition is the most critical aspect of degu care. Degus have a unique sensitivity to sugar and are highly prone to developing diabetes if fed an improper diet. Their digestive system is...","permalink":"/docs/Degus/getting-started/degu-nutrition"},{"id":"Ferrets/getting-started/ferret-nutrition","title":"Nutrition","description":"Understanding a ferret\'s diet is simple: they are obligate carnivores. This means their bodies are designed to digest and thrive on animal-based protein and fat exclusively. They cannot digest fiber,...","permalink":"/docs/Ferrets/getting-started/ferret-nutrition"},{"id":"Gerbils/getting-started/gerbil-nutrition","title":"Nutrition","description":"A balanced diet is essential for a gerbil\'s health and longevity. Unlike some other small pets, gerbils are prone to obesity and selective eating, so it\'s important to provide a diet that is both...","permalink":"/docs/Gerbils/getting-started/gerbil-nutrition"},{"id":"Hamsters/getting-started/hamster-nutrition","title":"Nutrition","description":"Providing a proper diet is fundamental to your hamster\'s health. Hamsters are omnivores and require a balanced diet of pellets, supplemented with small amounts of fresh foods. Understanding what to...","permalink":"/docs/Hamsters/getting-started/hamster-nutrition"},{"id":"Hedgehogs/getting-started/hedgehog-nutrition","title":"Nutrition","description":"Hedgehogs are insectivores, meaning their natural diet consists primarily of insects. In captivity, their diet is based on a high-quality, low-fat cat food, supplemented with insects and other...","permalink":"/docs/Hedgehogs/getting-started/hedgehog-nutrition"},{"id":"Mice/getting-started/mouse-nutrition","title":"Nutrition","description":"A proper diet is crucial for the health and well-being of pet mice. As omnivores, they require a balanced mix of grains, seeds, and protein. Providing the right food will help prevent obesity and...","permalink":"/docs/Mice/getting-started/mouse-nutrition"},{"id":"general-care/planning-and-preparedness/preparing-a-sitter","title":"preparing-a-sitter","description":"A comprehensive checklist and guide for preparing a pet sitter to care for your animals, ensuring a smooth, safe, and stress-free experience for everyone involved.","permalink":"/docs/general-care/planning-and-preparedness/preparing-a-sitter"},{"id":"guinea-pigs/getting-started/proper-handling-of-guinea-pigs","title":"proper-handling-of-guinea-pigs","description":"Proper handling is fundamental to building a trusting relationship with your guinea pig and ensuring their safety. As prey animals, guinea pigs can be naturally skittish and may be frightened by...","permalink":"/docs/guinea-pigs/getting-started/proper-handling-of-guinea-pigs"},{"id":"Rats/getting-started/rat-nutrition-guide","title":"rat-nutrition-guide","description":"Proper nutrition is the cornerstone of your pet rat\'s health and longevity. As omnivores, rats have specific dietary needs that must be met to prevent obesity, nutritional deficiencies, and other...","permalink":"/docs/Rats/getting-started/rat-nutrition-guide"},{"id":"general-care/getting-a-pet/rehome","title":"rehome","description":"We all hope to keep our pets forever, but sometimes life happens and unfortunately, we have to find a new home for our pets. Here is some advice for safely rehoming your pets.","permalink":"/docs/general-care/getting-a-pet/rehome"},{"id":"guinea-pigs/breeds-and-genetics/sexing-guinea-pigs","title":"sexing-guinea-pigs","description":"Correctly identifying the sex of a guinea pig is a crucial skill for any owner, breeder, or rescue. It is the only way to prevent accidental and unwanted pregnancies, which can be dangerous for...","permalink":"/docs/guinea-pigs/breeds-and-genetics/sexing-guinea-pigs"},{"id":"general-care/getting-a-pet/spayneuter","title":"spayneuter","description":"Animal shelters today are full of not only cats and dogs, but small animals like guinea pigs, rabbits, rats, and mice. While \u201coops\u201d litters seem common among pet owners, it\u2019s vital to understand that...","permalink":"/docs/general-care/getting-a-pet/spayneuter"},{"id":"guinea-pigs/getting-started/the-ideal-guinea-pig-habitat","title":"the-ideal-guinea-pig-habitat","description":"Creating a safe, spacious, and enriching environment is one of the most important responsibilities of a guinea pig owner. The right habitat directly impacts their physical health and mental...","permalink":"/docs/guinea-pigs/getting-started/the-ideal-guinea-pig-habitat"}],"unlisted":false}}')}}]);